def maskPII(S):
    if '@' in S:
        name, domain = S.split('@')
        name = name[0].lower() + '*' * 5 + name[-1].lower()
        return name + '@' + domain.lower()
    else:
        digits = [d for d in S if d.isdigit()]
        local = "***-***-" + ''.join(digits[-4:])
        if len(digits) == 10:
            return local
        else:
            return "+" + "*" * (len(digits) - 10) + "-" + local
